(7731306, 1273809, 67723, '<td valign="top">I love this!</td>', 'I love this!', '2022-10-19 07:50:20.000000', NULL, 1),
(7731307, 1273653, 67723, '<td valign="top">Wonderful in all aspects!</td>', 'Wonderful in all aspects!', '2022-10-19 07:50:39.000000', NULL, 1),
(7731309, 1273779, 83313, '<td valign="top">Great use of a drone. The rings of waves around the breakwater really add impact. I wonder what caused those? Looking again, that is probably not waves, but the patterns of sand under the water. The drone certainly could not have created those.</td>', 'Great use of a drone. The rings of waves around the breakwater really add impact. I wonder what caused those? Looking again, that is probably not waves, but the patterns of sand under the water. The drone certainly could not have created those.', '2022-10-19 10:30:44.000000', NULL, 1),
(7731339, 1273809, 114285, '<td valign="top">I knew there would be one drone shot depicting something like this :)</td>', 'I knew there would be one drone shot depicting something like this :)', '2022-10-19 21:45:05.000000', NULL, 1),
